//! Short UI copy translation backed by rune-i18n.
//!
//! Views specify an English key, which is looked up in compile-time catalogs
//! generated by `rune_i18n` from `desktop/locales/desktop/*.json`.
//! All 12 supported locales are compiled in. Traditional Chinese (Taiwan) is
//! derived offline from Simplified Chinese via OpenCC (`opencc -c s2twp.json`)
//! using `desktop/scripts/sync-i18n.py`.

use crate::config::Language;

/// Look up a string from the multi-language catalog by its English key.
pub fn t(language: Language, en: &str) -> String {
    match language {
        Language::En => en.to_string(),
        other => crate::ui::i18n::lookup(other, en)
            .map(|s| s.to_string())
            .unwrap_or_else(|| en.to_string()),
    }
}

/// Look up a static string from the multi-language catalog by its English key.
pub fn t_ref(language: Language, en: &'static str) -> &'static str {
    match language {
        Language::En => en,
        other => crate::ui::i18n::lookup(other, en).unwrap_or(en),
    }
}

/// Translate an English UI string into the active language.
pub fn tr(language: Language, en: &str) -> String {
    t(language, en)
}

/// Translate an English UI static string into the active language.
pub fn tr_ref(language: Language, en: &'static str) -> &'static str {
    t_ref(language, en)
}

/// Identity pass-through for runtime dynamic strings.
pub fn localize(_language: Language, text: String) -> String {
    text
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tr_ref_looks_up_locales() {
        assert_eq!(tr_ref(Language::En, "Settings"), "Settings");
        assert_eq!(
            tr_ref(Language::ZhCn, "Settings"),
            crate::ui::i18n::lookup(Language::ZhCn, "Settings").unwrap()
        );
        assert_eq!(
            tr_ref(Language::ZhTw, "Settings"),
            crate::ui::i18n::lookup(Language::ZhTw, "Settings").unwrap()
        );
        assert_eq!(
            tr_ref(Language::Ja, "Settings"),
            crate::ui::i18n::lookup(Language::Ja, "Settings").unwrap()
        );
    }
}
